import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections.CollectionUtils;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import quick.pager.shop.activity.client.BannerClient;
import quick.pager.shop.activity.request.banner.BannerOtherRequest;
import quick.pager.shop.constants.IConsts;
import quick.pager.shop.constants.ResponseStatus;
import quick.pager.shop.goods.request.spu.GoodsSpuOtherRequest;
import quick.pager.shop.goods.response.spu.GoodsSpuTreeResponse;
import quick.pager.shop.mapper.GoodsClassMapper;
import quick.pager.shop.mapper.GoodsSpuMapper;
import quick.pager.shop.model.GoodsClass;
import quick.pager.shop.model.GoodsSpu;
import quick.pager.shop.goods.request.spu.GoodsSpuPageRequest;
import quick.pager.shop.goods.request.spu.GoodsSpuSaveRequest;
import quick.pager.shop.goods.response.spu.GoodsSpuResponse;
import quick.pager.shop.service.GoodsSpuService;
import quick.pager.shop.user.response.Response;
import quick.pager.shop.utils.BeanCopier;
import quick.pager.shop.utils.DateUtils;

/**
 * <p>
 * 商品spu 服务实现类
 * </p>
 *
 * @author Siguiyang
 * @since 2019-10-07
 */
@Service
@Slf4j
public class GoodsSpuServiceImpl extends ServiceImpl<GoodsSpuMapper, GoodsSpu> implements GoodsSpuService {

    @Autowired
    private GoodsClassMapper goodsClassMapper;
    @Autowired
    private BannerClient bannerClient;

    @Override
    public Response<Long> create(GoodsSpuSaveRequest request) {
        if (StringUtils.isBlank(request.getSpuName())) {
            return Response.toError(ResponseStatus.Code.FAIL_CODE, "spu名称不能为空！");
        }
        if (checkName(request.getSpuName(), null)) {
            return Response.toError(ResponseStatus.Code.FAIL_CODE, "spu名称已存在！");
        }
        GoodsSpu spu = this.conv(request);
        spu.setCreateTime(DateUtils.dateTime());
        spu.setDeleteStatus(Boolean.FALSE);
        if (this.baseMapper.insert(spu) > 0) {
            return Response.toResponse(spu.getId());
        }
        log.error("新增SPU失败 result = {}", JSON.toJSONString(request));
        return Response.toError(ResponseStatus.Code.FAIL_CODE, "新增SPU失败");
    }

    @Override
    public Response<Long> modify(GoodsSpuSaveRequest request) {
        if (StringUtils.isNotBlank(request.getSpuName()) && checkName(request.getSpuName(), request.getId())) {
            return Response.toError(ResponseStatus.Code.FAIL_CODE, "spu名称已存在！");
        }
        GoodsSpu spu = this.conv(request);
        this.baseMapper.updateById(spu);
        return Response.toResponse(spu.getId());
    }

    @Override
    public Response<Long> delete(final Long id) {
        int delete = this.baseMapper.deleteById(id);
        if (delete > 0) {
            return Response.toResponse(id);
        }
        log.error("删除SPU失败 id = {}", id);
        return Response.toError(ResponseStatus.Code.FAIL_CODE, "删除SPU失败");
    }

    @Override
    public Response<List<GoodsSpuResponse>> queryPage(GoodsSpuPageRequest request) {
        System.out.println(bannerClient.queryList(new BannerOtherRequest()));
        Response<List<GoodsSpu>> response = this.toPage(request.getPage(), request.getPageSize(), new LambdaQueryWrapper<GoodsSpu>()
                .likeRight(StringUtils.isNotBlank(request.getSpuName()), GoodsSpu::getSpuName, request.getSpuName())
                .orderByAsc(GoodsSpu::getSequence));

        return Response.toResponse(response.getData().stream().map(this::conv).collect(Collectors.toList()), response.getTotal());
    }

    @Override
    public Response<List<GoodsSpuResponse>> queryList(GoodsSpuOtherRequest request) {

        List<GoodsSpu> goodsSpus = this.baseMapper.selectList(new LambdaQueryWrapper<GoodsSpu>()
                .eq(StringUtils.isNotEmpty(request.getSpuName()), GoodsSpu::getSpuName, request.getSpuName())
                .like(StringUtils.isNotEmpty(request.getKeyword()), GoodsSpu::getSpuName, request.getKeyword()));
        return Response.toResponse(goodsSpus.stream().map(this::conv).collect(Collectors.toList()));
    }

    @Override
    public Response<List<GoodsSpuTreeResponse>> spuTree() {

        List<GoodsSpu> goodsSpus = this.baseMapper.selectList(Wrappers.emptyWrapper());
        return Response.toResponse(goodsSpus.stream().map(item -> {
            GoodsSpuTreeResponse response = new GoodsSpuTreeResponse();
            response.setId(item.getId());
            response.setName(item.getSpuName());
            List<GoodsClass> goodsClasses = goodsClassMapper.selectList(new LambdaQueryWrapper<GoodsClass>()
                    .eq(GoodsClass::getSpuId, item.getId()));
            response.setChildren(goodsClasses.stream().map(gc -> {
                GoodsSpuTreeResponse gcRes = new GoodsSpuTreeResponse();
                gcRes.setId(gc.getId());
                gcRes.setName(gc.getClassName());
                return gcRes;
            }).collect(Collectors.toList()));
            return response;
        }).collect(Collectors.toList()));
    }

    private GoodsSpu conv(GoodsSpuSaveRequest request) {
        GoodsSpu spu = new GoodsSpu();
        BeanCopier.create(request, spu).copy();
        return spu;
    }


    private GoodsSpuResponse conv(GoodsSpu spu) {
        GoodsSpuResponse response = new GoodsSpuResponse();
        BeanCopier.create(spu, response).copy();
        return response;
    }


    /**
     * 校验名称的唯一性
     *
     * @param name spu名称
     * @param id   spu主键
     * @return true 表示已经存在，反之亦然
     */
    private Boolean checkName(final String name, final Long id) {
        List<GoodsSpu> spus = this.baseMapper.selectList(new LambdaQueryWrapper<GoodsSpu>()
                .eq(GoodsSpu::getSpuName, name));

        if (CollectionUtils.isEmpty(spus)) {
            return Boolean.FALSE;
        }

        return spus.stream()
                .filter(item -> Objects.isNull(id) ? Boolean.TRUE : IConsts.ZERO != item.getId().compareTo(id))
                .anyMatch(item -> item.getSpuName().equals(name));
    }
}
package quick.pager.shop.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import java.time.LocalDateTime;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import quick.pager.shop.constants.ResponseStatus;
import quick.pager.shop.job.enums.JobEnums;
import quick.pager.shop.job.enums.JobStatusEnums;
import quick.pager.shop.helper.JobHelper;
import quick.pager.shop.mapper.JobGroupMapper;
import quick.pager.shop.mapper.JobInfoMapper;
import quick.pager.shop.model.DTO;
import quick.pager.shop.model.JobGroup;
import quick.pager.shop.model.JobInfo;
import quick.pager.shop.job.request.JobGroupSaveRequest;
import quick.pager.shop.job.request.JobPageRequest;
import quick.pager.shop.job.request.JobRequest;
import quick.pager.shop.job.request.JobSaveRequest;
import quick.pager.shop.job.response.JobGroupResponse;
import quick.pager.shop.job.response.JobResponse;
import quick.pager.shop.service.JobService;
import quick.pager.shop.user.response.Response;
import quick.pager.shop.utils.BeanCopier;

/**
 * JobService 实现
 *
 * @author siguiyang
 */
@Service
public class JobServiceImpl implements JobService {

    @Autowired
    private JobInfoMapper jobInfoMapper;
    @Autowired
    private JobGroupMapper jobGroupMapper;

    @Override
    public Response<List<JobResponse>> queryPage(final JobPageRequest request) {

        LambdaQueryWrapper<JobInfo> qw = this.toQuery(request.getJobName(), request.getJobGroup(), request.getJobStatus());
        int total = jobInfoMapper.selectCount(qw);
        List<JobResponse> responseList = Collections.emptyList();
        if (total > 0) {
            IPage<JobInfo> page = jobInfoMapper.selectPage(new Page<>(request.getPage(), request.getPageSize()), qw);
            responseList = page.getRecords().stream()
                    .map(this::convert)
                    .collect(Collectors.toList());
        }
        return Response.toResponse(responseList, total);
    }

    @Override
    public Response<List<JobResponse>> queryList(final JobRequest request) {

        LambdaQueryWrapper<JobInfo> qw = this.toQuery(request.getJobName(), request.getJobGroup(), request.getJobStatus());
        List<JobInfo> list = jobInfoMapper.selectList(qw);
        return Response.toResponse(list.stream()
                .map(this::convert)
                .collect(Collectors.toList()), 0L);
    }

    @Override
    public Response<List<JobGroupResponse>> queryGroupList(String jobGroup) {
        LambdaQueryWrapper<JobGroup> wrapper = new LambdaQueryWrapper<>();
        if (StringUtils.isNotBlank(jobGroup)) {
            wrapper.likeRight(JobGroup::getGroupName, jobGroup);
        }

        List<JobGroup> jobGroups = jobGroupMapper.selectList(wrapper);

        return Response.toResponse(jobGroups.stream().map(item -> {
            JobGroupResponse jobGroupRes = new JobGroupResponse();
            jobGroupRes.setId(item.getId());
            jobGroupRes.setGroupName(item.getGroupName());
            jobGroupRes.setSequence(item.getSequence());
            return jobGroupRes;
        }).collect(Collectors.toList()));
    }

    @Override
    public Response<Long> create(final JobSaveRequest request) {

        JobGroup jobGroup = jobGroupMapper.selectById(request.getJobGroupId());
        if (Objects.isNull(jobGroup)) {
            return Response.toError(ResponseStatus.Code.FAIL_CODE, "任务组不存在");
        }
        JobInfo jobInfo = this.convert(request);
        jobInfo.setJobGroup(jobGroup.getGroupName());
        jobInfo.setJobStatus(JobStatusEnums.NORMAL.getCode());
        jobInfo.setCreateTime(LocalDateTime.now());
        jobInfo.setUpdateTime(LocalDateTime.now());
        jobInfoMapper.insert(jobInfo);
        JobHelper.execute(DTO.builder()
                .jobId(jobInfo.getId())
                .jobName(jobInfo.getJobName())
                .jobGroup(jobInfo.getJobGroup())
                .cron(jobInfo.getCron())
                .jobEnums(JobEnums.CREATE)
                .build());
        return Response.toResponse(jobInfo.getId());
    }

    @Override
    public Response<Long> create(final JobGroupSaveRequest request) {

        JobGroup jobGroup = new JobGroup();
        jobGroup.setGroupName(request.getName());
        jobGroup.setSequence(jobGroupMapper.selectMaxSequence());
        jobGroupMapper.insert(jobGroup);

        return Response.toResponse(jobGroup.getId());
    }

    @Override
    public Response<Long> modify(final JobSaveRequest request) {
        JobInfo jobInfo = this.convert(request);
        jobInfoMapper.updateById(jobInfo);
        return Response.toResponse(jobInfo.getId());
    }


    @Override
    public Response<JobResponse> info(final Long jobId) {
        JobInfo jobInfo = jobInfoMapper.selectById(jobId);
        return Response.toResponse(this.convert(jobInfo));
    }

    @Override
    public Response<String> doJob(final Long jobId, final String params, final JobEnums jobEnums) {
        JobInfo jobInfo = jobInfoMapper.selectById(jobId);
        if (Objects.isNull(jobInfo)) {
            return Response.toError(ResponseStatus.Code.FAIL_CODE, "未找到任务");
        }
        JobHelper.execute(DTO.builder().jobId(jobId).jobName(jobInfo.getJobName()).jobGroup(jobInfo.getJobGroup()).params(params).jobEnums(jobEnums).build());
        return Response.toResponse();
    }

    private LambdaQueryWrapper<JobInfo> toQuery(String jobName, String jobGroup, Integer jobStatus) {
        LambdaQueryWrapper<JobInfo> qw = new LambdaQueryWrapper<>();
        if (StringUtils.isNotEmpty(jobName)) {
            qw.eq(JobInfo::getJobName, jobName);
        }

        if (StringUtils.isNotEmpty(jobGroup)) {
            qw.eq(JobInfo::getJobGroup, jobGroup);
        }

        if (Objects.nonNull(jobStatus)) {
            qw.eq(JobInfo::getJobStatus, jobStatus);
        }

        return qw;
    }

    private JobResponse convert(JobInfo jobInfo) {
        JobResponse response = new JobResponse();
        BeanCopier.copy(jobInfo, response);
        JobStatusEnums jobStatusEnums = JobStatusEnums.parse(jobInfo.getJobStatus());
        response.setJobStatusName(Objects.nonNull(jobStatusEnums) ? jobStatusEnums.getDesc() : StringUtils.EMPTY);
        return response;
    }

    private JobInfo convert(JobSaveRequest request) {
        return BeanCopier.create(request, new JobInfo()).copy();
    }
}
package quick.pager.shop.service;

import com.alibaba.fastjson.JSON;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Service;
import quick.pager.shop.constants.Constants;
import quick.pager.shop.platform.dto.SystemConfigDTO;
import quick.pager.shop.user.response.Response;
import quick.pager.shop.response.EnumResponse;

/**
 * 通用枚举服务
 *
 * @author siguiyang
 */
@Service
public class CommonEnumService {

    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    public Response<Map<String, List<EnumResponse>>> getCommonEnumInfo() {

        Map<String, List<EnumResponse>> result = Maps.newHashMap();
        result.putIfAbsent(Constants.Type.OFFER_TYPE, getOfferType());
        result.putIfAbsent(Constants.Type.GOODS_TYPE, getGoodsType());
        result.putIfAbsent(Constants.Type.ORDER_TYPE, getOrderType());
        result.putIfAbsent(Constants.Type.ORDER_STATUS, getOrderStatus());
        result.putIfAbsent(Constants.Type.MODULE_TYPE, getModuleType());
        result.putIfAbsent(Constants.Type.BANNER_TYPE, getBannerType());
        result.putIfAbsent(Constants.Type.SHARE_CHANNEL, getBannerShareChannel());

        return Response.toResponse(result);
    }

    /**
     * 优惠券
     */
    private List<EnumResponse> getOfferType() {
        Long size = redisTemplate.opsForList().size("offer_type");

        if (Objects.nonNull(size)) {
            return getCommonInteger(redisTemplate.opsForList().range("offer_type", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * 商品类型
     */
    private List<EnumResponse> getGoodsType() {

        Long size = redisTemplate.opsForList().size("goods_type");

        if (Objects.nonNull(size)) {
            return getCommonInteger(redisTemplate.opsForList().range("goods_type", 0, size));
        }

        return Lists.newArrayList();
    }


    /**
     * 订单类型
     */
    private List<EnumResponse> getOrderType() {

        Long size = redisTemplate.opsForList().size("order_type");

        if (Objects.nonNull(size)) {
            return getCommonInteger(redisTemplate.opsForList().range("order_type", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * 订单状态
     */
    private List<EnumResponse> getOrderStatus() {

        Long size = redisTemplate.opsForList().size("order_status");

        if (Objects.nonNull(size)) {
            return getCommonString(redisTemplate.opsForList().range("order_status", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * 模块类型
     */
    private List<EnumResponse> getModuleType() {

        Long size = redisTemplate.opsForList().size("shop_module");

        if (Objects.nonNull(size)) {
            return getCommonString(redisTemplate.opsForList().range("shop_module", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * Banner类型
     */
    private List<EnumResponse> getBannerType() {

        Long size = redisTemplate.opsForList().size("banner_type");

        if (Objects.nonNull(size)) {
            return getCommonString(redisTemplate.opsForList().range("banner_type", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * Banner分享渠道
     */
    private List<EnumResponse> getBannerShareChannel() {

        Long size = redisTemplate.opsForList().size("share_channel");

        if (Objects.nonNull(size)) {
            return getCommonString(redisTemplate.opsForList().range("share_channel", 0, size));
        }

        return Lists.newArrayList();
    }

    /**
     * SystemConfig configValue 配置使用String型
     */
    private List<EnumResponse> getCommonString(final List<Object> result) {
        List<SystemConfigDTO> systemConfigs = JSON.parseArray(JSON.toJSONString(result), SystemConfigDTO.class);
        return Optional.ofNullable(systemConfigs).orElse(Lists.newArrayList()).stream()
                .map(config -> new EnumResponse(config.getConfigValue(), config.getConfigName()))
                .collect(Collectors.toList());
    }

    /**
     * SystemConfig configValue 配置使用int型
     */
    private List<EnumResponse> getCommonInteger(List<Object> result) {
        List<SystemConfigDTO> systemConfigs = JSON.parseArray(JSON.toJSONString(result), SystemConfigDTO.class);
        return Optional.ofNullable(systemConfigs).orElse(Lists.newArrayList()).stream()
                .map(config -> new EnumResponse(Integer.parseInt(config.getConfigValue()), config.getConfigName()))
                .collect(Collectors.toList());
    }
}
package quick.pager.shop.service;

import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.core.toolkit.StringPool;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.baomidou.mybatisplus.generator.AutoGenerator;
import com.baomidou.mybatisplus.generator.InjectionConfig;
import com.baomidou.mybatisplus.generator.config.DataSourceConfig;
import com.baomidou.mybatisplus.generator.config.FileOutConfig;
import com.baomidou.mybatisplus.generator.config.GlobalConfig;
import com.baomidou.mybatisplus.generator.config.PackageConfig;
import com.baomidou.mybatisplus.generator.config.StrategyConfig;
import com.baomidou.mybatisplus.generator.config.TemplateConfig;
import com.baomidou.mybatisplus.generator.config.po.TableInfo;
import com.baomidou.mybatisplus.generator.config.rules.NamingStrategy;
import com.baomidou.mybatisplus.generator.engine.FreemarkerTemplateEngine;
import java.text.MessageFormat;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import quick.pager.shop.param.system.GeneratorPageParam;
import quick.pager.shop.mapper.GeneratorMapper;
import quick.pager.shop.model.Columns;
import quick.pager.shop.model.Tables;
import quick.pager.shop.user.response.Response;

/**
 * @author siguiyang
 */
@Service
@Slf4j
public class GeneratorService {

    @Autowired
    private GeneratorMapper generatorMapper;

    /**
     * 所有表
     */
    public Response tables(GeneratorPageParam dto) {

        QueryWrapper<Tables> qw = new QueryWrapper<>();
        if (StringUtils.isNotBlank(dto.getTableSchema())) {
            qw.eq("TABLE_SCHEMA", dto.getTableSchema());
        }
        if (StringUtils.isNotBlank(dto.getTableName())) {
            qw.eq("TABLE_NAME", dto.getTableName());
        }

        IPage<Tables> page = generatorMapper.selectTables(new Page<>(dto.getPage(), dto.getPageSize()), qw);
        return Response.toResponse(page.getRecords(), page.getTotal());
    }

    /**
     * 某张表的元素信息
     *
     * @param tableSchema 数据库实例
     * @param tableName   表名
     */
    public Response<List<Columns>> tables(String tableSchema, String tableName) {
        QueryWrapper<Columns> qw = new QueryWrapper<>();
        if (StringUtils.isNotBlank(tableSchema)) {
            qw.eq("TABLE_SCHEMA", tableSchema);
        }
        if (StringUtils.isNotBlank(tableName)) {
            qw.eq("TABLE_NAME", tableName);
        }
        List<Columns> columns = generatorMapper.selectColumns(qw);
        return Response.toResponse(columns);
    }

    /**
     * 自动生成代码
     *
     * @param tableSchema 数据库空间
     * @param tableName   表名
     */
    public Response generator(String tableSchema, String tableName) {

        // 代码生成器
        AutoGenerator mpg = new AutoGenerator();

        // 全局配置
        GlobalConfig gc = new GlobalConfig();
        String projectPath = System.getProperty("user.dir");
        gc.setOutputDir(projectPath + "/shop/src/main/java");
        gc.setAuthor(System.getProperty("user.name"));
        gc.setOpen(false);
        mpg.setGlobalConfig(gc);

        // 数据源配置
        DataSourceConfig dsc = new DataSourceConfig();
        dsc.setUrl(MessageFormat.format("jdbc:mysql://localhost:3306/{0}?serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=UTF-8&useSSL=false", tableSchema));
        dsc.setDriverName("com.mysql.cj.jdbc.Driver");
        dsc.setUsername("root");
        dsc.setPassword("root");
        mpg.setDataSource(dsc);

        // 包配置
        PackageConfig pc = new PackageConfig();
        pc.setModuleName("shop");
        pc.setParent("quick.pager.shop");
        mpg.setPackageInfo(pc);

        // 自定义配置
        InjectionConfig cfg = new InjectionConfig() {
            @Override
            public void initMap() {
                // to do nothing
            }
        };
        List<FileOutConfig> focList = new ArrayList<>();
        focList.add(new FileOutConfig("/templates/mapper.xml.ftl") {
            @Override
            public String outputFile(TableInfo tableInfo) {
                // 自定义输入文件名称
                return projectPath + "/shop/src/main/resources/mapper/" + pc.getModuleName()
                        + "/" + tableInfo.getEntityName() + "Mapper" + StringPool.DOT_XML;
            }
        });
        cfg.setFileOutConfigList(focList);
        mpg.setCfg(cfg);
        mpg.setTemplate(new TemplateConfig().setXml(null));

        // 策略配置
        StrategyConfig strategy = new StrategyConfig();
        strategy.setNaming(NamingStrategy.underline_to_camel);
        strategy.setColumnNaming(NamingStrategy.underline_to_camel);
        strategy.setSuperEntityClass("quick.pager.shop.model.Model");
        strategy.setEntityLombokModel(true);
        strategy.setInclude(tableName);
        strategy.setSuperEntityColumns("id");
        strategy.setControllerMappingHyphenStyle(true);
        strategy.setTablePrefix(pc.getModuleName() + "_");
        mpg.setStrategy(strategy);
        mpg.setTemplateEngine(new FreemarkerTemplateEngine());
        mpg.execute();

        return Response.toResponse();
    }
}
